/**
 * Embed the cultivation artwork into the client bundle as data URIs.
 *
 * The host also serves the same files from /plugins/dsh-pixel-team/assets, but
 * a running host keeps its allowlist in memory: a rebuilt client would 404 on
 * every portrait until the whole app restarts. Embedding removes that coupling —
 * the art ships with the client it renders on.
 *
 * Run after scripts/gen-cultivation-art.mjs. Generated file; do not edit by hand.
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const ASSETS = join(import.meta.dirname, '..', 'assets', 'agent-teams')
const TARGET = join(import.meta.dirname, '..', 'src', 'client', 'art-data.ts')

const files = readdirSync(ASSETS).filter(name => name.endsWith('.png')).sort()
if (files.length === 0) throw new Error('no artwork found in ' + ASSETS)

const entries = files.map((name) => {
  const base64 = readFileSync(join(ASSETS, name)).toString('base64')
  return `  '${name}': '${base64}',`
})

const output = [
  '/**',
  ' * Generated by scripts/gen-art-data.mjs from assets/agent-teams/*.png.',
  ' * Base64 PNG payloads keyed by file name; artwork.ts wraps them as data URLs',
  ' * so portraits render without a host asset round-trip.',
  ' */',
  'export const ART_BASE64: Readonly<Record<string, string>> = {',
  ...entries,
  '}',
  '',
].join('\n')

writeFileSync(TARGET, output)
console.log(`wrote ${TARGET} with ${files.length} images`)
